NativeWorldDrawVertex V(float x,float y,float z,ScreenColor color,float w=1,float u=0,float v=0){return {{x*w,y*w,z*w,w},color,{u,v}};}
std::vector<NativeWorldDrawVertex> Quad(float lo,float hi,float z,ScreenColor color){return {V(lo,lo,z,color,1,0,0),V(hi,lo,z,color,1,1,0),V(hi,hi,z,color,1,1,1),V(lo,hi,z,color,1,0,1)};}
void Add(NativeWorldDrawRecorder& r,NativeDrawPrimitive mode,const std::vector<NativeWorldDrawVertex>& v,NativeWorldDrawState state={},ScreenDrawState surface={}){r.Record(NativeWorldDrawStage::World,mode,v,surface,state);}
